    pub fn step(&mut self) -> bool { self.advance() == SchedulerStatus::Progressed }
    fn process_after_step(&mut self) { }
    pub fn advance(&mut self) -> SchedulerStatus { let status = self.scheduler.advance(&mut self.state); self.process_after_step(); status }
    pub fn advance_frame(&mut self) -> SchedulerStatus { self.scheduler.script_ids_in_frame_order_into(&mut self.frame_order); let mut cursor = 0; let mut progressed = false; while cursor < self.frame_order.len() { let id = self.frame_order[cursor]; cursor += 1; if let Some(status) = self.scheduler.advance_script_id(id, &mut self.state) { if status == SchedulerStatus::Complete { return if self.state.has_active_sounds() { SchedulerStatus::WaitingForSignal } else { SchedulerStatus::Complete }; } progressed = true; } } let status = if progressed { SchedulerStatus::Progressed } else { self.scheduler.idle_status() }; status }
